.ix-loading-spinner > span { width: 100%; height: 100%; border: 1.5px solid currentColor; border-right-color: transparent; border-radius: 50%; animation: ix-spin 620ms linear infinite; }

@media (prefers-reduced-motion: reduce) {
.ix-loading-spinner > span { animation-duration: 2.4s; }
}

